//! `ay applet`: the one multicall of Unix applets (WinuxCmd is the base, uutils fills the gaps).
//!
//! Provider table: `infra/os/unixwin/applets.toml`, generated by `scripts/unixwin-applets.ts` from the per-applet matrix of
//! docs/native/UNIXWIN.md. `winux` applets run in process (`src/winux/cmds`, library-form functions with injected IO);
//! `uutils` applets run through the uutils multicall binary (`coreutils`) and `winux-cxx` applets through the WinuxCmd
//! executable, both found on PATH (`ay up` installs them), because they are not linkable Rust.
//!
//! Applets ported from C++ to portable Rust (`src/winux/extra`) run in process on every host.
//!
//! The WinuxCmd library is the Windows implementation (Win32 console, handles, ACLs): it is linked on Windows only. On other
//! hosts a `winux` applet runs through the uutils multicall, which implements the same GNU behavior natively.
//!
//!   ay applet --list [--json]     applets and their providers
//!   ay applet NAME [ARGS...]      run one applet

use std::collections::BTreeMap;
use std::ffi::OsString;
#[cfg(windows)]
use std::io::Write;

#[cfg(windows)]
use winux_core::{Ctx, Io, ProcessEnv};

const TABLE: &str = include_str!("../../../infra/os/unixwin/applets.toml");

/// Who runs an applet.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Provider {
    Winux,
    Uutils,
    WinuxCxx,
}

impl Provider {
    pub fn name(self) -> &'static str {
        match self {
            Provider::Winux => "winux",
            Provider::Uutils => "uutils",
            Provider::WinuxCxx => "winux-cxx",
        }
    }
}

/// One applet of the provider table: who runs it and, for uutils, through which executable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub provider: Provider,
    /// uutils: the repository's executable (`coreutils`, `procps`, `util-linux`, `grep`...).
    pub bin: Option<String>,
    /// uutils: `<bin> <applet> args` (multicall) or `<bin> args`.
    pub multicall: bool,
}

/// The provider table, sorted by applet name.
pub fn table() -> BTreeMap<String, Entry> {
    let doc: toml::Table = TABLE.parse().expect("infra/os/unixwin/applets.toml is valid TOML");
    doc.into_iter()
        .filter_map(|(name, v)| {
            let provider = match v.get("provider")?.as_str()? {
                "winux" => Provider::Winux,
                "uutils" => Provider::Uutils,
                "winux-cxx" => Provider::WinuxCxx,
                _ => return None,
            };
            let bin = v.get("bin").and_then(|b| b.as_str()).map(str::to_string);
            let multicall = v.get("multicall").and_then(|m| m.as_bool()).unwrap_or(false);
            Some((name, Entry { provider, bin, multicall }))
        })
        .collect()
}

/// The provider of every applet.
pub fn providers() -> BTreeMap<String, Provider> {
    table().into_iter().map(|(n, e)| (n, e.provider)).collect()
}

/// Run an applet from the in-process WinuxCmd library with the process's stdio, cwd and environment.
#[cfg(windows)]
pub fn run_winux(name: &str, args: &[OsString]) -> Option<i32> {
    let env = ProcessEnv;
    let ctx = Ctx::new(std::env::current_dir().unwrap_or_default(), &env);
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    let stderr = std::io::stderr();
    let (mut sin, mut sout, mut serr) = (stdin.lock(), stdout.lock(), stderr.lock());
    let mut io = Io { stdin: &mut sin, stdout: &mut sout, stderr: &mut serr };
    let result = winux_cmds::dispatch(name, args, &mut io, &ctx)?;
    // The library never flushes: the caller does.
    let _ = io.stdout.flush();
    let _ = io.stderr.flush();
    Some(match result {
        Ok(status) => status as i32,
        Err(_) => winux_core::ABI_FAILURE_STATUS as i32,
    })
}

/// Run an applet of the portable ports (`src/winux/extra`) in process, on any host.
pub fn run_extra(name: &str, args: &[OsString]) -> Option<i32> {
    use std::io::Write as _;
    let env = winux_core::ProcessEnv;
    let ctx = winux_core::Ctx::new(std::env::current_dir().unwrap_or_default(), &env);
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    let stderr = std::io::stderr();
    let (mut sin, mut sout, mut serr) = (stdin.lock(), stdout.lock(), stderr.lock());
    let mut io = winux_core::Io { stdin: &mut sin, stdout: &mut sout, stderr: &mut serr };
    let result = winux_extra::dispatch(name, args, &mut io, &ctx)?;
    let _ = io.stdout.flush();
    let _ = io.stderr.flush();
    Some(match result {
        Ok(status) => status as i32,
        Err(_) => winux_core::ABI_FAILURE_STATUS as i32,
    })
}

/// WinuxCmd applets by name; empty where the library is not linked (not Windows).
pub fn winux_registry() -> Vec<&'static str> {
    #[cfg(windows)]
    return winux_cmds::registry().into_iter().map(|(n, _)| n).collect();
    #[cfg(not(windows))]
    Vec::new()
}

/// The exit status of a child: its code, or 128 + the signal that ended it (the shell convention).
pub fn exit_code(status: std::process::ExitStatus) -> i32 {
    if let Some(code) = status.code() {
        return code;
    }
    #[cfg(unix)]
    {
        use std::os::unix::process::ExitStatusExt;
        if let Some(sig) = status.signal() {
            return 128 + sig;
        }
    }
    1
}

/// The command line of an external provider: `<bin> <applet> args` for a multicall binary, `<bin> args` otherwise.
pub fn external_argv(bin: &str, multicall: bool, applet: &str, args: &[OsString]) -> Vec<OsString> {
    let mut v = vec![OsString::from(bin)];
    if multicall {
        v.push(OsString::from(applet));
    }
    v.extend(args.iter().cloned());
    v
}

fn run_external(program: &str, multicall: bool, applet: &str, args: &[OsString]) -> i32 {
    let argv = external_argv(program, multicall, applet, args);
    let mut cmd = std::process::Command::new(&argv[0]);
    cmd.args(&argv[1..]);
    match cmd.status() {
        Ok(s) => exit_code(s),
        Err(e) => {
            eprintln!("ay applet: {applet}: needs `{program}` on PATH (`ay up`): {e}");
            127
        }
    }
}

/// `ay applet ...`; `args` excludes `applet`. Returns the exit status.
pub fn run(args: &[String]) -> i32 {
    let table = table();
    match args.first().map(String::as_str) {
        None | Some("-h" | "--help") => {
            eprintln!("usage: ay applet --list [--json] | ay applet NAME [ARGS...]");
            0
        }
        Some("--list") => {
            if args.iter().any(|a| a == "--json") {
                let map: BTreeMap<&str, &str> = table.iter().map(|(n, e)| (n.as_str(), e.provider.name())).collect();
                println!("{}", serde_json::to_string_pretty(&map).unwrap_or_default());
            } else {
                for (n, e) in &table {
                    println!("{n}\t{}", e.provider.name());
                }
            }
            0
        }
        Some(name) => {
            let rest: Vec<OsString> = args[1..].iter().map(OsString::from).collect();
            if let Some(code) = run_extra(name, &rest) {
                return code;
            }
            match table.get(name) {
                #[cfg(windows)]
                Some(Entry { provider: Provider::Winux, .. }) => run_winux(name, &rest).unwrap_or_else(|| {
                    eprintln!("ay applet: {name}: listed as winux but not in the library registry");
                    127
                }),
                // The WinuxCmd library is Win32 code: elsewhere the uutils executable of the same applet runs it.
                #[cfg(not(windows))]
                Some(Entry { provider: Provider::Winux, bin: Some(bin), multicall, .. }) => run_external(bin, *multicall, name, &rest),
                #[cfg(not(windows))]
                Some(Entry { provider: Provider::Winux, bin: None, .. }) => {
                    eprintln!("ay applet: {name}: implemented by the WinuxCmd Windows library only, no uutils applet on this host");
                    127
                }
                Some(Entry { provider: Provider::Uutils, bin, multicall, .. }) => run_external(bin.as_deref().unwrap_or(name), *multicall, name, &rest),
                Some(Entry { provider: Provider::WinuxCxx, .. }) => run_external("winuxcmd", true, name, &rest),
                None => {
                    eprintln!("ay applet: {name}: unknown applet (`ay applet --list`)");
                    127
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn os(a: &[&str]) -> Vec<OsString> {
        a.iter().map(OsString::from).collect()
    }

    #[test]
    fn table_has_the_three_providers_and_winuxcmd_is_the_base() {
        let t = providers();
        assert!(t.len() > 150);
        assert_eq!(t["basename"], Provider::Winux);
        assert!(t.values().any(|p| *p == Provider::Uutils));
        assert!(t.values().any(|p| *p == Provider::WinuxCxx));
    }

    #[cfg(windows)]
    #[test]
    fn every_winux_applet_of_the_table_is_in_the_library_registry() {
        // The WinuxCmd library (Windows) and the portable ports (every host) together are the `winux` provider.
        let mut registry = winux_registry();
        registry.extend(winux_extra::registry().into_iter().map(|(n, _)| n));
        for (name, p) in providers() {
            if p == Provider::Winux {
                assert!(registry.contains(&name.as_str()), "{name} is provided by winux but no registry has it");
            }
        }
    }

    #[cfg(unix)]
    #[test]
    fn a_child_killed_by_a_signal_exits_128_plus_the_signal() {
        let status = std::process::Command::new("sh").args(["-c", "kill -TERM $$"]).status().unwrap();
        assert_eq!(exit_code(status), 128 + 15);
    }

    #[test]
    fn external_command_lines() {
        let a = os(&["-x"]);
        assert_eq!(external_argv("procps", true, "ps", &a), os(&["procps", "ps", "-x"]));
        assert_eq!(external_argv("grep", false, "grep", &a), os(&["grep", "-x"]));
    }

    #[test]
    fn uutils_applets_name_their_own_executable_and_libraries_are_not_applets() {
        let t = table();
        assert_eq!(t["ps"].bin.as_deref(), Some("procps"));
        assert!(t["ps"].multicall);
        assert_eq!(t["cal"].bin.as_deref(), Some("util-linux"));
        assert_eq!(t["grep"].bin.as_deref(), Some("grep"));
        assert!(!t["grep"].multicall);
        assert!(t.values().filter(|e| e.provider == Provider::Uutils).all(|e| e.bin.is_some()));
        assert!(!t.contains_key("checksum_common"));
    }

    #[test]
    fn ported_applets_run_in_process_on_every_host() {
        assert_eq!(run_extra("dos2unix", &os(&["--bogus"])), Some(1));
        assert_eq!(run_extra("nope", &os(&[])), None);
        for (name, _) in winux_extra::registry() {
            assert_eq!(providers()[name], Provider::Winux, "{name} must be provided by winux");
        }
    }

    #[cfg(windows)]
    #[test]
    fn a_winux_applet_runs_in_process() {
        assert_eq!(run_winux("true", &os(&[])), Some(0));
        assert_eq!(run_winux("false", &os(&[])), Some(1));
        assert_eq!(run_winux("no-such-applet", &os(&[])), None);
        assert_eq!(run(&["--list".to_string()]), 0);
        assert_eq!(run(&["no-such-applet".to_string()]), 127);
    }
}

#[cfg(all(test, not(windows)))]
mod tests_unix {
    use super::*;

    #[test]
    fn unknown_applets_and_listing() {
        assert_eq!(run(&["--list".to_string()]), 0);
        assert_eq!(run(&["no-such-applet".to_string()]), 127);
        assert!(winux_registry().is_empty());
    }
}
